ALTER TABLE public.auto_campaign_action_detail_statuses ADD COLUMN description text NOT NULL DEFAULT 'Danh mục trạng thái chi tiết chiến dịch, không phải policy lỗi hay lịch sử một lần chạy. Đọc campaign_action_id để biết loại chiến dịch; action_code NULL nghĩa là mọi hành động trong loại đó, có giá trị nghĩa là chỉ hành động đó. status_value được so khớp không phân biệt hoa/thường; label chỉ để hiển thị. status_id NULL nghĩa là chưa gắn nhóm ngữ nghĩa auto_status, không phải dữ liệu hỏng. Không suy ra thành công, retry, khóa tài khoản hoặc kết quả gửi/nhận từ việc có dòng danh mục; đối chiếu detail/log và runtime. Dòng có thể được seed, lưu từ Automation hoặc tự sinh khi runtime ghi detail. Mô tả chỉ phục vụ agent, không tham gia điều kiện chạy.'::text;
COMMENT ON COLUMN public.auto_campaign_action_detail_statuses.description IS 'Agent-readable documentation only. Not executed or used for Automation matching. New auto-generated rows inherit a generic explanation; curated rows have contextual descriptions. NULL action_code is a wildcard, NULL status_id means no semantic group.';
UPDATE public.auto_campaign_action_detail_statuses t SET description=d.description FROM jsonb_to_recordset($source_descriptions$[{"id":1,"description":"Loại chiến dịch: sms_send. Phạm vi: mọi hành động của loại chiến dịch (action_code=NULL). Trạng thái: thành công. Runtime ghi nhận hành động hoàn tất thành công theo hợp đồng của hành động; không tự suy ra người nhận đã đọc, email đã vào inbox hoặc lời mời đã được chấp nhận. Nhóm ngữ nghĩa auto_status.id=20; không thay thế điều kiện status_value/action_code. Đây là danh mục lựa chọn Automation, không chứng minh đã có lượt chạy phát ra trạng thái. So khớp status_value không phân biệt hoa/thường; action_code NULL là wildcard. Dòng có sẵn trước v347, giữ nguyên ID/điều kiện/trạng thái. Không giả định chuỗi lịch sử còn được mọi phiên bản runtime phát ra. Mô tả cho agent, không điều khiển runtime."},{"id":2,"description":"Loại chiến dịch: sms_send. Phạm vi: mọi hành động của loại chiến dịch (action_code=NULL). Trạng thái: thất bại. Runtime ghi nhận hành động không hoàn tất thành công; nguyên nhân nằm trong detail/log/error_code. Không tự suy ra có thể retry. Nhóm ngữ nghĩa auto_status.id=21; không thay thế điều kiện status_value/action_code. Đây là danh mục lựa chọn Automation, không chứng minh đã có lượt chạy phát ra trạng thái. So khớp status_value không phân biệt hoa/thường; action_code NULL là wildcard. Dòng có sẵn trước v347, giữ nguyên ID/điều kiện/trạng thái. Không giả định chuỗi lịch sử còn được mọi phiên bản runtime phát ra. Mô tả cho agent, không điều khiển runtime."},{"id":3,"description":"Loại chiến dịch: sms_send. Phạm vi: mọi hành động của loại chiến dịch (action_code=NULL). Trạng thái: lỗi. Runtime ghi nhận lỗi khi xử lý hành động; đây là trạng thái detail, không phải mã err_* hay chỉ thị retry/khóa tài khoản. Nhóm ngữ nghĩa auto_status.id=22; không thay thế điều kiện status_value/action_code. Đây là danh mục lựa chọn Automation, không chứng minh đã có lượt chạy phát ra trạng thái. So khớp status_value khôn